USE studyflow;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS subjects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,code VARCHAR(30),description TEXT,weekly_hours DECIMAL(4,1) NOT NULL DEFAULT 0,color VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_subject_user_name(user_id,name),KEY idx_subject_user(user_id),CONSTRAINT fk_subject_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED,title VARCHAR(180) NOT NULL,description TEXT,due_at DATETIME,estimated_minutes INT UNSIGNED NOT NULL DEFAULT 60,priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',status ENUM('pending','in_progress','completed') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_assignment_user_due(user_id,due_at),CONSTRAINT fk_assignment_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_assignment_subject FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS examinations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED,title VARCHAR(180) NOT NULL,exam_at DATETIME NOT NULL,chapter_info TEXT,notes TEXT,priority ENUM('low','medium','high','urgent') NOT NULL DEFAULT 'medium',preparation_progress TINYINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_exam_user_date(user_id,exam_at),CONSTRAINT fk_exam_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_exam_subject FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,CHECK(preparation_progress<=100)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS study_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED,assignment_id BIGINT UNSIGNED,examination_id BIGINT UNSIGNED,title VARCHAR(180) NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,duration_minutes INT UNSIGNED NOT NULL,status ENUM('scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'scheduled',is_locked BOOLEAN NOT NULL DEFAULT FALSE,reason VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_session_user_start(user_id,start_at),CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_session_subject FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,CONSTRAINT fk_session_assignment FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE SET NULL,CONSTRAINT fk_session_exam FOREIGN KEY(examination_id) REFERENCES examinations(id) ON DELETE SET NULL,CHECK(end_at>start_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS availability_slots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,day_of_week TINYINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_availability_user_start(user_id,start_at),CONSTRAINT fk_availability_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CHECK(end_at>start_at),CHECK(day_of_week IS NULL OR day_of_week<=6)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS timetable_preferences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,session_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 50,short_break_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 10,long_break_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 25,max_daily_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 240,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_preferences_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS study_goals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT,goal_type ENUM('daily','weekly','monthly','custom') NOT NULL DEFAULT 'weekly',target_minutes INT UNSIGNED NOT NULL DEFAULT 300,start_date DATE,end_date DATE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_goal_user_active(user_id,is_active),CONSTRAINT fk_goal_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS daily_goal_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,goal_id BIGINT UNSIGNED NOT NULL,progress_date DATE NOT NULL,completed_minutes INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_goal_progress(goal_id,progress_date),CONSTRAINT fk_progress_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_progress_goal FOREIGN KEY(goal_id) REFERENCES study_goals(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(180) NOT NULL,message TEXT,is_read BOOLEAN NOT NULL DEFAULT FALSE,related_id BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_notification_user_read(user_id,is_read,created_at),CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_reset_user(user_id),CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
